// Some portions generated by Claude
import { computeNetworkLayout, separateLayoutRectangles } from './graph-layout-network.ts';
import { componentGraphs, packLayoutComponents, layoutNodeFixed } from './graph-layout-topology.ts';
import { computeMultilevelLayout } from './graph-layout-multilevel.ts';
import { computeGroupedLayout, layoutNeighborhoods } from './graph-layout-groups.ts';
import { computeSparseLayout } from './graph-layout-sparse.ts';
import { optimizeEdgeBends } from './graph-geometry.ts';
import { refineLayoutGeometry } from './graph-layout.ts';
import {layoutScoreGeometry, layoutCandidateScore} from './graph-layout-score.ts';
import {improveLayoutReadability} from './graph-layout-readability.ts';
import {computeHubNeighborhoodLayout} from './graph-layout-hub.ts';
import type { Graph, PointerPosition } from './graph-types.ts';

export type LayoutOptions = {
  incremental?: boolean;
  localNodeIds?: Set<string> | null;
  movableNodeIds?: Set<string>;
  refine?: boolean;
  seed?: number;
  aspectRatio?: number;
  mode?: 'network' | 'hierarchy';
  nodeSizes?: Map<string, {width: number; height: number}>;
  groups?: readonly {id: string; nodeIds: readonly string[]}[];
  repairOnly?: boolean;
};
export type LayoutResult = {positions: Map<string, PointerPosition>; bends: Map<string, number>; grouped?: boolean; fixedOverlaps?: number; protectedNodeIds?: Set<string>};

function organizeComponent(graph: Graph, options: LayoutOptions): LayoutResult {
  const hub = computeHubNeighborhoodLayout(graph, options, core => organizeComponent(core, options));
  if (hub) return hub;
  // Two deterministic starts reduce local minima on medium exploration graphs.
  // Only organize changes the global arrangement. Refine/expand keep the map.
  const multiStart = graph.nodes.length >= 80 && graph.nodes.length <= 350 && graph.edges.length <= 600 &&
    !options.refine && !options.incremental && !options.localNodeIds?.size && !graph.nodes.some(n => n.pinned);
  let best: LayoutResult | undefined, bestScore = Infinity;
  const seen = new Set<string>();
  for (const seed of multiStart ? [42, 101] : [42]) {
    const grouped = computeGroupedLayout(graph, {...options, seed});
    const candidates: LayoutResult[] = [grouped ?? computeNetworkLayout(graph, {...options, seed})];
    // Topology is evidence, not an instruction to force compounds. Compare a
    // flat candidate when grouping is automatic; explicit named groups win.
    if (grouped && seed === 42 && !options.groups?.length && graph.nodes.length <= 1000 && graph.edges.length <= 1600) {
      candidates.push(computeNetworkLayout(graph, {...options, seed}));
    }
    for (const candidate of candidates) {
      // Specialized deterministic layouts (notably pure stars) may return the
      // same proposal for both seeds. Do not repeat their expensive cleanup.
      const signature = `${Boolean(candidate.grouped)}:` + graph.nodes.map(node => {
        const p = candidate.positions.get(node.id)!; return `${p.x},${p.y}`;
      }).join(';');
      if (seen.has(signature)) continue;
      seen.add(signature);
      if (!candidate.grouped && graph.nodes.length <= 350 && graph.edges.length <= 500) {
        const g = layoutScoreGeometry(graph, candidate.positions, options);
        refineLayoutGeometry(g.nodes, g.edges, {passes: 2, radiusScale: .7});
        g.nodes.forEach(node => candidate.positions.set(node.entityId, {x: node.x, y: node.y}));
        separateLayoutRectangles(graph, candidate.positions, options);
      }
      if (!multiStart && candidates.length === 1) return candidate;
      const score = layoutCandidateScore(graph, candidate.positions, options);
      if (score < bestScore) {bestScore = score; best = candidate;}
    }
  }
  return best!;
}

export async function computeGraphLayout(graph: Graph, options: LayoutOptions = {}): Promise<LayoutResult> {
  if (!graph.nodes.length) return {positions: new Map(), bends: new Map()};
  const checked = (result: LayoutResult) => {
    const status = separateLayoutRectangles(graph, result.positions, {...options, repairOnly: true});
    result.fixedOverlaps = status.fixedOverlaps;
    return result;
  };
  if (options.repairOnly) {
    let repair: LayoutResult = computeSparseLayout(graph, options);
    const moved = graph.nodes.some(node => {const p = repair.positions.get(node.id)!; return p.x !== (node.x ?? 0) || p.y !== (node.y ?? 0);});
    // Size hydration must not organize a clear, manually arranged map merely
    // because its abstract group bounding boxes interleave.
    if (moved) repair = computeGroupedLayout(graph, options) ?? repair;
    checked(repair);
    if (graph.nodes.length <= 1500) repair.bends = optimizeEdgeBends(graph.nodes.map(n => ({...n, ...repair.positions.get(n.id)})), graph.edges, graph.edges.length <= 1600 ? 1 : 0);
    return repair;
  }
  const constrained = graph.nodes.some(node => layoutNodeFixed(node, options));
  if (options.refine && graph.nodes.length <= 1500) {
    // Refine is a local, monotonic readability repair. Re-running fCoSE here
    // used to erase deliberate placement even when no conflicts existed.
    const result = checked(computeSparseLayout(graph, {...options, repairOnly: true}));
    improveLayoutReadability(graph, result.positions, options, layoutNeighborhoods(graph, options).groups);
    result.bends = optimizeEdgeBends(graph.nodes.map(n => ({...n, ...result.positions.get(n.id)})), graph.edges, graph.edges.length <= 1600 ? 1 : 0);
    return result;
  }
  if (graph.nodes.length > 1500) {
    if (options.groups?.length) {
      const grouped = computeGroupedLayout(graph, options);
      if (grouped) return checked(grouped);
    }
    // Keep edits to an existing large map local; full organization is coarsened.
    return checked(constrained || options.refine ? computeSparseLayout(graph, {...options, incremental: true,
      movableNodeIds: options.incremental ? options.movableNodeIds : new Set(graph.nodes.filter(n => !layoutNodeFixed(n, options)).map(n => n.id)),
    }) : computeMultilevelLayout(graph, options));
  }
  let result: LayoutResult;
  if (options.mode === 'hierarchy' && !constrained && !options.refine) {
    const {computeGraphvizLayout} = await import('./graph-layout-graphviz.ts');
    result = await computeGraphvizLayout(graph, 'dot');
  } else {
    const parts = constrained || options.refine || options.groups?.length ? [graph] : componentGraphs(graph);
    const positions = new Map<string, PointerPosition>();
    const protectedNodeIds = new Set<string>();
    let grouped = false;
    for (const part of parts) {
      const organized = organizeComponent(part, options);
      grouped ||= Boolean(organized.grouped);
      organized.protectedNodeIds?.forEach(id => protectedNodeIds.add(id));
      for (const [id, p] of organized.positions) positions.set(id, p);
    }
    if (!constrained && !options.refine) packLayoutComponents(parts, positions, options.aspectRatio);
    result = {positions, bends: new Map(), grouped, protectedNodeIds};
  }
  checked(result);
  const cleanupGraph = result.protectedNodeIds?.size ? {...graph, nodes: graph.nodes.map(n =>
    result.protectedNodeIds!.has(n.id) ? {...n, pinned: true} : n)} : graph;
  if (options.mode !== 'hierarchy') improveLayoutReadability(cleanupGraph, result.positions, options,
    result.grouped ? layoutNeighborhoods(graph, options).groups : []);
  const placed = graph.nodes.map(node => ({...node, ...result.positions.get(node.id)}));
  // Routing is worker-only and bounded. Medium graphs used to skip this pass.
  result.bends = optimizeEdgeBends(placed, graph.edges, graph.edges.length <= 500 ? 2 : graph.edges.length <= 1600 ? 1 : 0);
  return result;
}
